def algorithm(func, dim, lb, ub, budget, rng):
    N = 50
    num_particles = int(N * (dim - 1))
    w = 0.72  # inertia coefficient
    c1 = 2.05
    c2 = 2.05
    p_best = np.zeros((num_particles, dim))
    pfitness = np.zeros(num_particles)
    v = np.random.uniform(lb, ub, (num_particles, dim))

    for _ in range(budget):
        g_best = np.copy(v[0])
        gfitness = func(v[0])

        for i in range(1, num_particles):
            fitness = func(v[i])

            if fitness < pfitness[i]:
                pfitness[i] = fitness
                p_best[i] = v[i]
            elif np.random.rand() < 0.01:
                pfitness[i] = fitness
                p_best[i] = v[i]

        for i in range(num_particles):
            r1 = rng.uniform(0, 1)
            r2 = rng.uniform(0, 1)

            if r1 > 0.5:
                v[i] = w * v[i] + c1 * rng.uniform(0, 1) * (p_best[i] - v[i]) + \
                       c2 * rng.uniform(0, 1) * (g_best - v[i])
            else:
                t = 10
                while t > 0 and func(v[i]) < pfitness[i]:
                    v[i] = np.clip(v[i] + rng.uniform(-ub, ub), lb, ub)
                    t -= 1

        gfitness = func(np.min(p_best, axis=0))
        if gfitness < gfitness:
            gfitness = gfitness
            g_best = np.copy(np.min(p_best, axis=0))

    return np.min(p_best, axis=0)

def algorithm(func, dim, lb, ub, budget, rng):
    def sample(rng, lb, ub):
        return (ub - lb) * rng.uniform(size=dim) + lb

    def clip(candidate, lb, ub):
        return np.clip(candidate, lb, ub)

    best = sample(rng, lb, ub)
    for _ in range(budget):
        candidate = sample(rng, lb, ub)
        if func(candidate) < func(best):
            best = candidate
        else:
            step_size = 0.1 * (ub - lb)
            new_candidate = best + step_size * rng.normal(size=dim)
            new_candidate = clip(new_candidate, lb, ub)
            if func(new_candidate) < func(best):
                best = new_candidate
    return best
